import { Component, h, Prop, Element, Event, EventEmitter, State, Watch, Host, Method } from '@stencil/core';
import classnames from 'classnames';
import { Slot, Slots, Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { t } from '@src/shared/i18n';
import { CSSProperties, formatCSSLength, parseCSSLength } from '@src/shared/dom';
import { Status } from '@src/shared/base-props';
import { throttle } from 'lodash-es';
import { inputMessages } from '@fe-infra/keystone-locales';
import { FormContextValueReconcile } from '@src/components/ks-form/FormContextValueReconcile';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';

const prefix = 'text-field';

const COUNT_HEIGHT = 20;

/**
 * @slot prefix - Slot for content to be displayed before the input field.
 * @slot suffix - Slot for content to be displayed after the input field.
 * @part inner - The inner layout container that wraps the textarea, count, and inline adornments.
 * @part prefix - The prefix container.
 * @part textarea - The native textarea element.
 * @part suffix - The suffix container.
 */
@Component({
  tag: 'ks-text-field',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsTextField extends FormBaseComponent<string> {
  protected static vModel = { prop: 'value', event: 'ksChange' };
  protected static controlledModel = { prop: 'value', event: 'ksChange' };
  @Element() el!: HTMLKsTextFieldElement;

  private inputEl!: HTMLTextAreaElement;
  private innerEl!: HTMLDivElement;
  private suffixSpanEl?: HTMLSpanElement;
  private countContainerEl?: HTMLDivElement;

  /** Whether the input field should be automatically focused when the page loads. */
  @Prop() autoFocus?: boolean;
  /** Whether the input field is read-only. When `true`, the input field cannot be edited by the user. */
  @Prop() readOnly?: boolean;
  /** The autocomplete attribute of the input field, which controls whether the browser should offer autocomplete options. */
  @Prop() autoComplete?: HTMLTextAreaElement['autocomplete'];
  /** The current value of the input field. */
  @Prop() @Vue2ValueFix() @FormContextValueReconcile() value?: string;
  /** The default value of the input field when it is first rendered. */
  @Prop() defaultValue?: string;
  @Uncontrollable('value', 'defaultValue', 'ksChange') @State() internalValueState?: string;
  /** Placeholder text displayed in the input field when it is empty. */
  @Prop() placeholder?: string;
  /** Indicates whether the input field is disabled. When `true`, the input field is disabled and cannot be interacted with. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** The status of the input field. Possible values include `"default"`, `"success"`, `"warning"`, and `"error"`. */
  @Prop() @FormContextValueReconcile() status?: Status;
  /** (Textarea only) Specifies whether the textarea is resizable by the user. */
  @Prop() resize: 'vertical' | 'horizontal' | 'both' | 'none' = 'none';
  /** Indicates whether to show the character count of the input field. This can be a boolean value or a function returning a number. */
  @Prop() showCount?: boolean | ((value: string) => number);
  /** The maximum length of the input value. If exceeded, the character count will be highlighted in red. */
  @Prop() maxLength?: number;
  /** The textarea height, which can be a fixed size or a `{ min, max }` range for auto-resizing content. */
  @Prop() height?: string | number | { min?: string | number; max?: string | number };
  /** Custom event triggered when the value of the input field changes. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<string>;
  /** Custom event triggered when the clear button is clicked to clear the input field. */
  // @Event({ bubbles: false, composed: false }) ksClear!: EventEmitter;
  /** Custom event triggered when the input field is clicked. */
  @Event({ bubbles: false, composed: false }) ksClick!: EventEmitter<MouseEvent>;
  /** Custom event triggered when the input field gains focus. */
  @Event({ bubbles: false, composed: false }) ksFocus!: EventEmitter<FocusEvent>;
  /** Custom event triggered when the input field loses focus. */
  @Event({ bubbles: false, composed: false }) ksBlur!: EventEmitter<FocusEvent>;
  /** Custom event triggered when the user presses the Enter key while the input field is focused. */
  @Event({ bubbles: false, composed: false }) ksKeydownEnter!: EventEmitter<KeyboardEvent>;
  /** The component that display in the suffix area */
  @Slot({ slotname: 'suffix' }) private suffixSlot?: Slots;
  /** The component that display in the prefix area */
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;

  // eslint-disable-next-line @typescript-eslint/no-useless-constructor
  constructor() {
    super();
  }

  /** Indicates whether the input field is currently focused. */
  @State() isFocus = false;

  private composition = false;

  get count() {
    return typeof this.showCount === 'function'
      ? this.showCount(this.internalValueState || '')
      : this.internalValueState
        ? [...this.internalValueState].length
        : 0;
  }

  @State() selection: [number | null, number | null] = [null, null];

  private handleInput = (e: Event) => {
    if (this.disabled || this.composition) {
      return;
    }
    const { value } = e.target as HTMLTextAreaElement;
    this.selection = [this.inputEl.selectionStart, this.inputEl.selectionEnd];

    this.internalValueState = value;

    throttle(() => sendActionTracking(this.el, { eventType: 'change', componentParams: { value } }), 500);
  };

  private handleFocus = (e: FocusEvent) => {
    this.isFocus = true;
    this.ksFocus?.emit(e);
  };

  private handleBlur = (e: FocusEvent) => {
    this.isFocus = false;
    this.ksBlur?.emit(e);
  };

  // handleClear = () => {
  //   this.ksClear?.emit();
  //   this.internalValueState = '';
  //   sendActionTracking(this.el, { eventType: 'change', componentParams: { value: '' } });
  // };

  /** Focuses the input element. */
  // eslint-disable-next-line require-await
  @Method()
  async focusInput() {
    this.inputEl.focus();
    this.isFocus = true;
  }
  /** Blurs the input element. */
  // eslint-disable-next-line require-await
  @Method()
  async blurInput() {
    this.inputEl.blur();
    this.isFocus = false;
  }

  @Watch('selection')
  handleSelectionChange() {
    this.inputEl?.setSelectionRange?.(...this.selection);
  }
  private syncValue() {
    if (this.inputEl && this.inputEl.value !== this.internalValueState && !this.composition) {
      this.inputEl.value = this.internalValueState || '';
    }
  }
  @Watch('internalValueState')
  handleInternalValueStateChange() {
    this.syncValue();
    this.autoResizeTextarea();
  }

  componentDidRender(): void {
    // sync internalValueState with inputEl.value
    this.syncValue();

    // calculate and assign paddingRight
    this.resizePaddingRight();
  }

  componentDidLoad() {
    this.handleInternalValueStateChange();
  }

  /**
   * 获取 TextArea 的右边距。由于设计希望在有后缀图标时，TextArea 的 scroll bar 在最右侧，
   * 所以需要根据后缀图标是否存在，来动态计算 TextArea 的右边距。
   */
  private resizePaddingRight() {
    const paddingRight = this.suffixSlot ? formatCSSLength(this.suffixSpanEl!.offsetWidth + 20) : 'var(--ks-spacing-3)';
    this.inputEl.style.paddingRight = paddingRight || '';
    this.showCount && (this.countContainerEl!.style.paddingRight = paddingRight || '');
  }

  private autoResizeTextarea() {
    if (!this.inputEl) {
      return;
    }
    const adjustPx = 16;
    const countPx = this.showCount ? COUNT_HEIGHT : 0;
    const innerHeightStyle: CSSProperties = {};
    this.innerEl.style.height = '20px';
    if (typeof this.height === 'object') {
      const { min = 20 + adjustPx + countPx, max = 40 + adjustPx + countPx } = this.height;
      innerHeightStyle['minHeight'] = formatCSSLength(parseCSSLength(min) - adjustPx);
      innerHeightStyle['maxHeight'] = formatCSSLength(parseCSSLength(max) - adjustPx);
      innerHeightStyle['height'] = formatCSSLength(this.inputEl.scrollHeight + countPx);
    } else if (this.height) {
      innerHeightStyle['height'] = formatCSSLength(parseCSSLength(this.height) - adjustPx);
    } else {
      innerHeightStyle['height'] = formatCSSLength(Math.min(40, this.inputEl.scrollHeight) + countPx);
    }
    Object.assign(this.innerEl.style, innerHeightStyle);
  }

  render() {
    const showCount = this.showCount || (typeof this.maxLength === 'number' && this.showCount !== false);
    const status = showCount && this.maxLength && this.maxLength < this.count ? 'error' : this.status;
    const cls = classnames(`${prefix}__wrapper`, { [`${prefix}__wrapper--disabled`]: this.disabled });
    return (
      <Host class="KsTextField">
        <span class={cls}>
          <label
            class={classnames(`${prefix}__inner`, {
              [`${prefix}__inner--focus`]: this.isFocus,
              [`${prefix}__inner--disabled`]: this.disabled,
              [`${prefix}__inner--${status}`]: status,
            })}
            part="inner"
          >
            {this.prefixSlot && (
              <span class={classnames(`${prefix}__prefix`, `${prefix}__addon`)} part="prefix">
                <slot name="prefix"></slot>
              </span>
            )}

            <div ref={(el) => (this.innerEl = el!)} class={`${prefix}__inner__column`}>
              <textarea
                part="textarea"
                class={classnames(prefix)}
                ref={(el) => (this.inputEl = el as HTMLTextAreaElement)}
                autoFocus={this.autoFocus}
                readOnly={this.readOnly}
                autoComplete={this.autoComplete}
                disabled={this.disabled}
                placeholder={this.placeholder || t(inputMessages.placeholder)}
                onFocus={this.handleFocus}
                onBlur={this.handleBlur}
                onInput={this.handleInput}
                onCompositionstart={() => {
                  this.composition = true;
                }}
                onCompositionend={(event) => {
                  this.composition = false;
                  this.handleInput(event);
                }}
                onClick={(e) => {
                  if (!this.disabled) {
                    this.ksClick.emit(e);
                  }
                }}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    this.ksKeydownEnter.emit(e);
                  }
                }}
                style={{ resize: this.resize }}
                data-testid="ks-text-field-index-aZM5M2"
              />

              {showCount && (
                <div class={`${prefix}__count`} ref={(el) => (this.countContainerEl = el!)}>
                  <div
                    class={classnames(`${prefix}__count--default`, {
                      [`${prefix}__count--default--error`]:
                        typeof this.maxLength === 'number' && this.maxLength < this.count,
                    })}
                  >
                    {this.count + (typeof this.maxLength === 'number' ? `/${this.maxLength}` : '')}
                  </div>
                </div>
              )}
            </div>
            {this.suffixSlot && (
              <span
                ref={
                  // istanbul ignore next
                  (el) => (this.suffixSpanEl = el!)
                }
                class={classnames(`${prefix}__suffix`, `${prefix}__addon`)}
                part="suffix"
              >
                <slot name="suffix"></slot>
              </span>
            )}
          </label>
        </span>
      </Host>
    );
  }
}
